// MRSSP Scoring Engine — 5-Dimension Protocol
// Weights: Gate Time 25%, Precision 25%, Efficiency 20%, Decision 15%, Recovery 15%

function vrn(base, variance = 8) {
  return Math.min(100, Math.max(0, base + (Math.random() - 0.5) * 2 * variance));
}

const vehicles = $input.all().map(item => JSON.parse(item.json));
const isClassB = (id) => id.startsWith('AUTO-') || id.startsWith('PAYLOAD-');

const scores = vehicles.map(v => {
  const classB = isClassB(v.vehicle_id);
  const prev = v.prev_scores || { gateTime: 78, precision: 82, efficiency: 80, decision: 78, recovery: 76 };

  const gateTime   = vrn(prev.gateTime, 6);
  const precision  = vrn(prev.precision + (classB ? 0 : 5), 6);
  const efficiency = vrn(prev.efficiency, 6);
  const decision   = vrn(prev.decision   + (classB ? 7 : 0), 6);
  const recovery   = vrn(prev.recovery   + (classB ? 7 : 0), 6);
  const composite  = gateTime * 0.25 + precision * 0.25 + efficiency * 0.20 + decision * 0.15 + recovery * 0.15;

  return {
    vehicle_id: v.vehicle_id,
    race_id: v.race_id,
    scored_at: new Date().toISOString(),
    scores: { gateTime, precision, efficiency, decision, recovery, composite: Math.round(composite * 10) / 10 },
    battery_pct: v.battery_pct
  };
});

return scores.map(s => ({ json: s }));
